struct Builder {
    hir: HirModule,
    params: HashMap<String, Vec<f32>>,
    i64_params: HashMap<String, Vec<i64>>,
    env: HashMap<String, HirNodeId>,
}

impl Builder {
    fn new() -> Self {
        Self {
            hir: HirModule::new("ppocrv6_small_rec_rlx"),
            params: HashMap::new(),
            i64_params: HashMap::new(),
            env: HashMap::new(),
        }
    }
    fn m(&mut self) -> HirMut<'_> {
        HirMut::new(&mut self.hir)
    }
    fn bind(&mut self, name: &str, id: HirNodeId) {
        self.env.insert(name.to_string(), id);
    }
    fn tensor(&self, name: &str) -> Result<HirNodeId> {
        self.env
            .get(name)
            .copied()
            .with_context(|| format!("tensor {:?}", name))
    }
    fn bind_param(&mut self, key: &str, shape: &[usize], data: Vec<f32>) -> HirNodeId {
        let id = HirMut::new(&mut self.hir).param(key, Shape::new(shape, DType::F32));
        self.params.insert(key.to_string(), data);
        id
    }
    fn bind_param_i64(&mut self, key: &str, shape: &[usize], data: Vec<i64>) -> HirNodeId {
        let id = HirMut::new(&mut self.hir).param(key, Shape::new(shape, DType::I64));
        self.i64_params.insert(key.to_string(), data);
        id
    }
    fn i64_data(&self, name: &str) -> Result<&[i64]> {
        self.i64_params
            .get(name)
            .map(|v| v.as_slice())
            .with_context(|| format!("i64 tensor {:?}", name))
    }
}

fn reshape_dims_from_i64(numel: usize, raw: &[i64], input_dims: &[usize]) -> Vec<i64> {
    let mut dims: Vec<i64> = raw.to_vec();
    // ONNX: 0 means copy from the corresponding input dimension.
    for (i, d) in dims.iter_mut().enumerate() {
        if *d == 0 {
            if let Some(&id) = input_dims.get(i) {
                *d = id as i64;
            }
        }
    }
    if let Some(neg) = dims.iter().position(|&d| d < 0) {
        let known: i64 = dims.iter().filter(|&&d| d > 0).product();
        let known = known.max(1) as usize;
        dims[neg] = (numel / known.max(1)) as i64;
    }
    dims
}

